-- Name: Offer status wise NPS - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH offer_session AS ( SELECT mri_session_id, MAX( CASE WHEN offer_response = 'FAILURE' THEN 1 ELSE 0 END ) AS has_failure, MAX( CASE WHEN offer_response = 'SUCCESS' THEN 1 ELSE 0 END ) AS has_success, COUNT( DISTINCT CASE WHEN COALESCE(TRIM(offer_code), '') <> '' THEN offer_code END ) AS distinct_offer_codes FROM user_interaction.order_info_details WHERE __time >= TIMESTAMP '2026-05-31 18:30:00' AND __time < TIMESTAMP '2026-06-14 18:30:00' AND country = 'IND' AND rb_user_id > 0 AND src_id IS NOT NULL AND dest_id IS NOT NULL AND mri_session_id IS NOT NULL -- AND os = 'Android' -- Uncomment if needed GROUP BY 1 ), confirm AS ( SELECT DISTINCT t.tin, CASE WHEN p.offer_campaign_id > 0 THEN 'Offer Txn' ELSE 'Non Offer Txn' END AS offer_txn, t.order_uuid, t.mri_session_id FROM transaction.bus_payment_events p INNER JOIN transaction.bus_ticket_events t ON p.order_uuid = t.order_uuid WHERE p.time_of_event >= TIMESTAMP '2026-05-31 17:30:00' AND p.time_of_event < TIMESTAMP '2026-06-14 19:30:00' AND p.country_code = 'IND' AND t.time_of_event >= TIMESTAMP '2026-05-31 17:30:00' AND t.time_of_event < TIMESTAMP '2026-06-14 19:30:00' AND t.country_code = 'IND' AND t.tin IS NOT NULL AND t.event_class = 2 AND t.event_type = 101 ), tin_categorized AS ( SELECT c.tin, c.order_uuid, c.mri_session_id, c.offer_txn, CASE WHEN os.has_failure = 0 AND c.offer_txn = 'Offer Txn' THEN 'Did not experience a failure and booked with offer' WHEN os.has_failure = 1 AND os.has_success = 1 AND c.offer_txn = 'Offer Txn' THEN 'Experienced a failure, had another code and booked with offer' WHEN os.has_failure = 1 AND c.offer_txn = 'Non Offer Txn' THEN 'Experienced a failure and booked without offer' END AS category FROM confirm c LEFT JOIN offer_session os ON c.mri_session_id = os.mri_session_id ) , -- SELECT -- category, -- COUNT(DISTINCT tin) booked_tins -- FROM tin_categorized -- GROUP BY 1 -- ORDER BY 2 DESC; NPS AS ( SELECT DISTINCT DATE(DATE_ADD('MINUTE', 330, a.received_on)) AS ReceivedOn, a.survey_id AS SurveyId, a.redbus_userid AS rb_user_id, -- CASE WHEN a.question_option_id = 17 THEN 0 ELSE a.question_option_id END AS NPS_Score, CASE WHEN a.question_option_id IN (17, 1, 2, 3, 4, 5, 6, 0) THEN 'Detractors' WHEN a.question_option_id IN (7, 8) THEN 'Neutrals' WHEN a.question_option_id IN (9, 10) THEN 'Promoters' END AS NPS_Type, CASE WHEN a.survey_id = 9 THEN 'Booking' WHEN a.survey_id = 1 THEN 'Travel' ELSE 'Cancellation' END AS Survey_Type, -- a.email, -- a.mobile_number AS mobilenumber, a.order_number AS ordernumber, a.business_unit AS businessunit, a.feedback, a.channel, n.operator_id AS bo_id, n.service_provider_name AS bo_name, -- c.survey_info, n.selected_language, CASE WHEN n.operator_id IN ( 10283, 16081, 6392, 15447, 8065, 15129, 7115, 10244, 10823, 15130, 11060, 15499, 11044, 3030, 15443, 16124, 16227, 2020, 16374, 16426, 16580, 16647, 16777, 17012, 16884, 4040, 17137, 17101, 17889, 18115, 18101, 18237, 18491, 19393, 19502, 22837, 22875, 22878, 24978, 25187, 25946, 27000, 26936, 27455, 28011, 29176, 29479, 29391, 29392, 32000, 32272, 32245, 34300, 34400, 33740, 35303, 35268, 33000) THEN 'RTC' ELSE 'Pvt' END AS RTC, n.user_type, n.route_id, -- CASE WHEN (n.source_location_id, n.destination_location_id) IN (SELECT src_id, dest_id FROM "lis"."short_route_sds") THEN 'Short Route' ELSE 'Long Route' END AS route_cohort n.date_of_issue AS bookingtime, n.date_of_journey, n.boarding_time, t.category -- COALESCE(CAST(bc.time_of_event AS VARCHAR), 'Not Cancelled') AS cancellationtime, -- COALESCE(bc.cancellation_type, 'Not Cancelled') AS cancellationtype FROM "ugc"."nps_survey_response" AS a -- LEFT JOIN "ugc"."nps_survey_info_response" AS c -- ON a.key = c.key LEFT JOIN "transaction"."bus_ticket_events" AS n ON a.order_number = n.tin -- LEFT JOIN "transaction"."bus_cancellation_events" AS bc -- ON a.order_number = bc.tin LEFT JOIN tin_categorized t ON n.tin = t.tin WHERE a.received_on >= TIMESTAMP '2026-05-31 18:30:00' AND a.received_on < TIMESTAMP '2026-06-14 21:30:00' AND n.time_of_event >= TIMESTAMP '2026-05-31 18:30:00' AND n.time_of_event < TIMESTAMP '2026-06-14 21:30:00' AND a.question_option_id <> -1 AND a.business_unit = 1 AND a.country_code = 1 AND n.country_code = 'IND' AND t.category IS NOT NULL -- AND bc.country_code = 'IND' -- ORDER BY ReceivedOn ) SELECT category, channel, Survey_Type, COUNT(DISTINCT CASE WHEN NPS_Type = 'Promoters' THEN (ReceivedOn, rb_user_id) END) AS Promoters_nps_received, COUNT(DISTINCT CASE WHEN NPS_Type = 'Neutrals' THEN (ReceivedOn, rb_user_id) END) AS Neutrals_nps_received, COUNT(DISTINCT CASE WHEN NPS_Type = 'Detractors' THEN (ReceivedOn, rb_user_id) END) AS Detractors_nps_received, COUNT(DISTINCT (ReceivedOn, rb_user_id)) Overall_nps_received FROM NPS GROUP BY 1, 2, 3 ORDER BY 1, 2, 3
NPS for tins categorized into Did not experience a failure and booked with offer Experienced a failure and booked without offer Experienced a failure, had another code and booked with offer
